package org.eclipse.kura.rest.provider.test.jwt;

import org.eclipse.kura.rest.provider.test.util.AbstractJwtRestScenario;
import org.junit.Test;

public class RefreshTokenFamilyRevocationTest extends AbstractJwtRestScenario {

    private static final String NEW_PASSWORD = "Jwt-Password-2!";

    @Test
    public void changingThePasswordRevokesTheRefreshTokenFamily() throws Exception {
        givenAnIdentityWithPermissions(ASSETS_PERMISSION);
        givenATokenPairIssuedToTheIdentity();
        givenTheIdentityChangedItsPasswordTo(NEW_PASSWORD);

        whenTheRefreshEndpointReceives(theRefreshToken());

        thenResponseCodeIs(401);
    }

    @Test
    public void reCreatingTheIdentityDoesNotReviveTheRefreshTokenFamily() throws Exception {
        givenAnIdentityWithPermissions(ASSETS_PERMISSION);
        givenATokenPairIssuedToTheIdentity();
        givenTheIdentityIs(IdentityChange.DELETED);
        givenTheRefreshTokenWasExchangedWithStatus(401);
        givenAnIdentityWithPermissions(ASSETS_PERMISSION);

        whenTheRefreshEndpointReceives(theRefreshToken());

        thenResponseCodeIs(401);
    }
}
